 #include "pamauthenticator.h"
 #include "pamauthenticatormodel.h"
 #include "pamauthenticators.h"
+#include "unlockpin.h"

 using namespace Qt::StringLiterals;

+// After this many wrong answers only the password unlocks, so that a short PIN can't be guessed
+constexpr int maxUnlockPinAttempts = 5;
+
 struct PamAuthenticators::Private {
     std::unique_ptr<PamAuthenticator> m_activeAuthenticator = nullptr;
     std::unique_ptr<PamAuthenticator> m_fingerprintAuthenticator = nullptr;
@@ -29,6 +34,7 @@ struct PamAuthenticators::Private {
     AuthenticatorsState state = AuthenticatorsState::Idle;
     bool graceLocked = false;
     bool hadPrompt = false;
+    int unlockPinAttempts = 0;
     /*! Whether the authenticators is locked. This only turns false if any authenticator reports succeeded */
     bool locked = true;

@@ -300,10 +306,29 @@ QString PamAuthenticators::errorMessage() const

 void PamAuthenticators::respond(const QByteArray &response)
 {
+    if (tryUnlockPin(response)) {
+        return;
+    }
     qCDebug(KSCREENLOCKER_GREET) << "PamAuthenticators: responding to interactive authenticator";
     d->m_activeAuthenticator->respond(response);
 }

+bool PamAuthenticators::tryUnlockPin(const QByteArray &response)
+{
+    const QString pinHash = KScreenSaverSettingsBase::self()->unlockPinHash();
+    if (m_authenticator != Authenticator::Regular || pinHash.isEmpty() || d->unlockPinAttempts >= maxUnlockPinAttempts) {
+        return false;
+    }
+    if (!UnlockPin::matches(response, pinHash)) {
+        d->unlockPinAttempts++;
+        return false;
+    }
+    qCDebug(KSCREENLOCKER_GREET) << "PamAuthenticators: unlocked with the unlock PIN";
+    d->locked = false;
+    Q_EMIT succeeded();
+    return true;
+}
+
 void PamAuthenticators::cancel()
 {
     qCDebug(KSCREENLOCKER_GREET) << "PamAuthenticators: cancelling interactive authenticator";
