diff --git a/settings/unlockpin.cpp b/settings/unlockpin.cpp
new file mode 100644
index 00000000..c3245d8a
--- /dev/null
+++ b/settings/unlockpin.cpp
@@ -0,0 +1,59 @@
+/*
+SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+#include "unlockpin.h"
+
+#include <QPasswordDigestor>
+#include <QRandomGenerator>
+#include <QStringList>
+
+using namespace Qt::StringLiterals;
+
+namespace
+{
+constexpr auto algorithm = QCryptographicHash::Sha512;
+constexpr int iterations = 100000;
+constexpr int saltLength = 16;
+constexpr int keyLength = 64;
+const auto prefix = u"pbkdf2-sha512"_s;
+
+QByteArray derive(const QByteArray &pin, const QByteArray &salt, int rounds)
+{
+    return QPasswordDigestor::deriveKeyPbkdf2(algorithm, pin, salt, rounds, keyLength);
+}
+}
+
+QString UnlockPin::hash(const QString &pin)
+{
+    if (pin.isEmpty()) {
+        return {};
+    }
+    QByteArray salt(saltLength, Qt::Uninitialized);
+    QRandomGenerator::system()->fillRange(reinterpret_cast<quint32 *>(salt.data()), saltLength / sizeof(quint32));
+    const QByteArray key = derive(pin.toUtf8(), salt, iterations);
+    return u"%1$%2$%3$%4"_s.arg(prefix, QString::number(iterations), QString::fromLatin1(salt.toBase64()), QString::fromLatin1(key.toBase64()));
+}
+
+bool UnlockPin::matches(const QByteArray &pin, const QString &hash)
+{
+    const QStringList parts = hash.split(u'$');
+    if (pin.isEmpty() || parts.size() != 4 || parts[0] != prefix) {
+        return false;
+    }
+    bool ok = false;
+    const int rounds = parts[1].toInt(&ok);
+    const QByteArray salt = QByteArray::fromBase64(parts[2].toLatin1());
+    const QByteArray key = QByteArray::fromBase64(parts[3].toLatin1());
+    if (!ok || rounds <= 0 || salt.isEmpty() || key.size() != keyLength) {
+        return false;
+    }
+    const QByteArray candidate = derive(pin, salt, rounds);
+    // Compare in constant time
+    char difference = 0;
+    for (int i = 0; i < keyLength; ++i) {
+        difference |= candidate[i] ^ key[i];
+    }
+    return difference == 0;
+}
